<script setup lang="ts">
import { useAuthService } from 'src/composables/useAuthService';
import { useAuthStore } from '@stores/auth-store';
import { useMapMenuStore } from '@stores/map/map-menu-store';
import { LocalStorage, useQuasar } from 'quasar';
import { ref, computed, watchEffect } from 'vue';
import AuthService from 'src/services/auth';
import WdVersionsPanel from 'src/components/version/WdVersionsPanel.vue';
import WdOverlayConfig from './overlay-config/WdOverlayConfig.vue';
import { useUserSettingsStore } from '@stores/user-settings-store';

const authStore = useAuthStore();
const menuStore = useMapMenuStore();
const userSettings = useUserSettingsStore();
const $q = useQuasar();

let $auth: AuthService | undefined = undefined;
if (process.env.CLIENT) {
  $auth = useAuthService();
}

const tracking = ref<boolean>(
  LocalStorage.hasItem('umami.disabled')
    ? !(LocalStorage.getItem('umami.disabled') as boolean)
    : true
);

watchEffect(() => {
  if (!tracking.value) {
    LocalStorage.set('umami.disabled', !tracking.value);
  } else {
    LocalStorage.removeItem('umami.disabled');
  }
});

// Computed properties for type-safe access to menuData
const overlayName = computed(() => menuStore.menuData.overlayName as string | undefined);
const initialTab = computed(() => menuStore.menuData.initialTab as string | undefined);
const menuTitle = computed(() => menuStore.menuData.title as string | undefined);

function handleOverlayConfigClose() {
  menuStore.closeMenu();
}

// Toolbar-like layout = the menu drawer carries the utility toolbar
// (MainLayout showDrawerToolbar: mobile AND the 770-1099px band where the
// left-aligned pill hides under the open drawer — its WdMenuButton close
// is the only exit there). The content must clear the ~50px toolbar —
// the drawer-mobile offsets below. ≥ 1100px has no toolbar:
// drawer-desktop anchors to the drawer top.
const toolbarLike = computed(() => $q.screen.width < 1100);
</script>
<style scoped>
.drawer-desktop {
  position: absolute;
  bottom: 80px;
  top: 0;
  left: 0;
  right: 0;
  height: calc(100vh - 40px);
  height: calc(100dvh - 40px);
}

.drawer-mobile {
  /* anchor to the drawer's real box (not 100vh math, which lies on
  mobile browsers with dynamic URL bars): flush top under the header,
  flush bottom - the version footer lands exactly at the drawer bottom
  on desktop emulation AND real phones. The toolbar carries the
  status-bar safe-area padding in the native app, so it must be added
  here too - a fixed 51px leaves the content overlapping the (taller)
  toolbar and swallowing its taps. */
  position: absolute;
  top: calc(51px + var(--q-safe-area-inset-top, env(safe-area-inset-top, 0px)));
  left: 0;
  right: 0;
  bottom: 0;
}

.map-menu__versions {
  /* Solid surface: translucent glass bled underlying content through */
  background: var(--wd-surface-deep, #112119);
  /* border-radius: 0px; */
}
</style>

<template>
  <div
    :class="{
      'drawer-desktop': !toolbarLike,
      'drawer-mobile': toolbarLike,
    }"
  >
    <!-- DEFAULT MENU -->
    <div v-if="menuStore.menuType === 'default'">
      <div class="flex flex-center" style="min-height: 32vh">
        <q-icon size="80px">
          <IconNotoV1Construction />
        </q-icon>
      </div>
      <div class="bg-transparent absolute-bottom">
        <div class="q-pa-xs column q-gutter-sm">
          <q-btn
            v-if="!authStore.isLoggedIn"
            :color="$q.dark.isActive ? 'secondary-200' : 'secondary-800'"
            unelevated
            flat
            @click="$auth?.signinRedirect()"
            :label="$t('login')"
          />
          <q-btn
            v-else
            :color="$q.dark.isActive ? 'accent-200' : 'accent-800'"
            unelevated
            flat
            @click="$auth?.logout()"
            :label="$t('logout')"
          />
        </div>

        <!-- Map display settings (cluster count badges on clustered
             overlay markers — clusters themselves always render) -->
        <div class="q-px-sm q-pb-sm">
          <q-item tag="label" v-ripple dense>
            <q-item-section>
              <q-item-label>{{ $t('overlays.cluster_counts') }}</q-item-label>
              <q-item-label class="text-caption">
                {{ $t('overlays.cluster_counts_caption') }}
              </q-item-label>
            </q-item-section>
            <q-item-section side>
              <q-toggle
                color="accent"
                :model-value="userSettings.uiSettings.overlayClusterCounts"
                @update:model-value="
                  userSettings.updateUISetting('overlayClusterCounts', Boolean($event))
                "
              />
            </q-item-section>
          </q-item>
        </div>

        <div class="">
          <!-- Privacy Policy Link -->
          <div v-if="authStore.isEditor()" class="text-center q-mb-sm">
            <router-link
              :to="{ name: 'data-policy' }"
              target="_blank"
              :class="$q.dark.isActive ? 'text-secondary-200' : 'text-secondary-800'"
            >
              Datenschutz
            </router-link>
          </div>

          <!-- Version Information -->
          <WdVersionsPanel class="map-menu__versions" />
        </div>
      </div>
    </div>

    <!-- OVERLAY CONFIG MENU -->
    <div v-else-if="menuStore.menuType === 'overlay-config'" class="overlay-config-container fit">
      <!-- Overlay Config Component (without dialog wrapper) -->
      <WdOverlayConfig
        v-if="overlayName"
        :overlay-name="overlayName"
        :initial-tab="initialTab"
        :show-as-page="true"
        :title="menuTitle || 'Overlay'"
        @close="handleOverlayConfigClose"
      />
    </div>
  </div>
</template>
