<script setup lang="ts">
/**
 * Legend Section Component
 *
 * Renders a legend section with items based on type.
 * Supports multiple rendering modes for symbols and geometric shapes.
 */

import type { LegendItem, LegendSection } from '@stores/map/overlay-configs/types';

interface Props {
  section: LegendSection;
}

defineProps<Props>();

/** Solid swatches paint the background; dashed/dotted swatches paint a
 * repeating gradient of the item color (currentColor of the wrapper). */
function dashStyle(item: LegendItem): Record<string, string> {
  if (!item.dash || item.dash === 'solid') {
    return { backgroundColor: item.color || '#000' };
  }
  return { color: item.color || '#000' };
}
</script>

<template>
  <div>
    <!-- Section Description -->
    <div v-if="section.description" class="text-caption wd-ink-soft-text q-mb-md">
      {{ section.description }}
    </div>

    <!-- Legend Items -->
    <q-list class="transparent">
      <q-item v-for="(item, index) in section.items" :key="index" class="q-px-none">
        <q-item-section side>
          <!-- Symbol: Detailed Icon Only -->
          <template v-if="section.type === 'symbol_color'">
            <q-avatar v-if="item.metadata?.iconColor || item.icon" size="38px" square>
              <img :src="item.metadata?.iconColor || item.icon" :alt="item.label" />
            </q-avatar>
          </template>

          <!-- Symbol: Simple Icon Only -->
          <template v-else-if="section.type === 'symbol_primitive'">
            <q-avatar v-if="item.metadata?.iconPrimitive || item.icon" size="28px" square>
              <img :src="item.metadata?.iconPrimitive || item.icon" :alt="item.label" />
            </q-avatar>
          </template>

          <!-- Symbol: Monochrome Icon Only -->
          <template v-else-if="section.type === 'symbol_mono'">
            <q-avatar v-if="item.metadata?.iconMono || item.icon" size="32px" square>
              <img :src="item.metadata?.iconMono || item.icon" :alt="item.label" />
            </q-avatar>
          </template>

          <!-- Symbol: Dual Icons (detailed + simple side-by-side) -->
          <template v-else-if="section.type === 'symbol_dual'">
            <div class="row items-center q-gutter-sm">
              <q-avatar v-if="item.metadata?.iconColor" size="38px" square>
                <img :src="item.metadata.iconColor" :alt="`${item.label} (color)`" />
              </q-avatar>

              <q-avatar v-if="item.metadata?.iconPrimitive" size="28px" square>
                <img :src="item.metadata.iconPrimitive" :alt="`${item.label} (primitive)`" />
              </q-avatar>

              <!-- Fallback: Show color if icons not available -->
              <div
                v-if="!item.metadata?.iconColor && !item.metadata?.iconPrimitive && item.color"
                class="point-indicator"
                :style="{ backgroundColor: item.color }"
              />
            </div>
          </template>

          <!-- Line: Colored line (solid, dashed or dotted — dash encodes
               difficulty for overlays like hiking) -->
          <template v-else-if="section.type === 'line'">
            <div
              class="line-indicator"
              :class="item.dash && item.dash !== 'solid' ? `line-indicator--${item.dash}` : ''"
              :style="dashStyle(item)"
            />
          </template>

          <!-- Area: Colored rectangle -->
          <template v-else-if="section.type === 'area'">
            <div class="area-indicator" :style="{ backgroundColor: item.color || '#000' }" />
          </template>

          <!-- Point: Colored circle -->
          <template v-else-if="section.type === 'point'">
            <div class="point-indicator" :style="{ backgroundColor: item.color || '#000' }" />
          </template>

          <!-- Fallback: Auto-detect based on available data -->
          <template v-else>
            <!-- Show icon if available -->
            <q-avatar
              v-if="item.icon || item.metadata?.iconColor || item.metadata?.iconPrimitive"
              size="32px"
              square
            >
              <img
                :src="(item.icon || item.metadata?.iconColor || item.metadata?.iconPrimitive) ?? ''"
                :alt="item.label"
              />
            </q-avatar>
            <!-- Otherwise show color point -->
            <div
              v-else-if="item.color"
              class="point-indicator"
              :style="{ backgroundColor: item.color }"
            />
          </template>
        </q-item-section>

        <!-- Item Label and Description -->
        <q-item-section>
          <q-item-label>{{ item.label }}</q-item-label>
          <q-item-label v-if="item.description" caption class="wd-ink-soft-text">
            {{ item.description }}
          </q-item-label>
        </q-item-section>
      </q-item>
    </q-list>
  </div>
</template>

<style scoped lang="scss">
.wd-ink-soft-text {
  color: var(--wd-ink-soft) !important;
}
.line-indicator {
  width: 40px;
  height: 3px;
  border-radius: 1.5px;
}

.line-indicator--dashed {
  background: repeating-linear-gradient(to right, currentColor 0 6px, transparent 6px 10px);
}

.line-indicator--dotted {
  background-image: radial-gradient(circle, currentColor 1.5px, transparent 1.6px);
  background-size: 7px 3px;
  background-repeat: repeat-x;
  background-position: center;
}

.area-indicator {
  width: 32px;
  height: 32px;
  border-radius: 4px;
  border: 1px solid rgba(0, 0, 0, 0.1);
}

.point-indicator {
  width: 16px;
  height: 16px;
  border-radius: 50%;
  border: 1px solid rgba(0, 0, 0, 0.1);
}
</style>
